def get_Inv_Count(arr):
    # Implement the inversion count using a modified merge sort approach
    # This approach efficiently counts inversions in O(n log n) time
    def merge_sort_and_count(arr, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        inv_count = merge_sort_and_count(arr, left, mid)
        inv_count += merge_sort_and_count(arr, mid + 1, right)
        inv_count += merge_and_count(arr, left, mid, right)
        return inv_count

    def merge_and_count(arr, left_start, left_end, right_end):
        temp = []
        left = left_start
        right = left_end + 1
        inv_count = 0

        while left <= left_end and right <= right_end:
            if arr[left] <= arr[right]:
                temp.append(arr[left])
                left += 1
            else:
                temp.append(arr[right])
                inv_count += (left_end - left + 1)  # All remaining left elements are inversions
                right += 1

        while left <= left_end:
            temp.append(arr[left])
            left += 1

        while right <= right_end:
            temp.append(arr[right])
            right += 1

        for i in range(len(temp)):
            arr[left_start + i] = temp[i]

        return inv_count

    return merge_sort_and_count(arr, 0, len(arr) - 1)
